window.THREE = window.THREE || {};

// Minimal THREE.js stub for compilation
THREE.Vector3 = class {
    constructor(x = 0, y = 0, z = 0) {
        this.x = x; this.y = y; this.z = z;
    }
    copy(v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; }
    subVectors(a, b) { this.x = a.x - b.x; this.y = a.y - b.y; this.z = a.z - b.z; return this; }
    multiplyScalar(s) { this.x *= s; this.y *= s; this.z *= s; return this; }
    add(v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; }
    lerpVectors(a, b, t) {
        this.x = a.x + (b.x - a.x) * t;
        this.y = a.y + (b.y - a.y) * t;
        this.z = a.z + (b.z - a.z) * t;
        return this;
    }
};

THREE.Color = class {
    constructor() { this.r = 0; this.g = 0; this.b = 0; }
    setHSL() { this.r = 0.5; this.g = 0.8; this.b = 0.9; return this; }
};

THREE.Scene = class { constructor() { this.background = null; } };
THREE.PerspectiveCamera = class {
    constructor() { this.position = new THREE.Vector3(); this.aspect = 1; }
    updateProjectionMatrix() {}
};
THREE.WebGLRenderer = class {
    constructor() { this.domElement = document.createElement('canvas'); }
    setSize() {}
    setPixelRatio() {}
    render() {}
};
THREE.BufferGeometry = class {
    setAttribute() {}
};
THREE.BufferAttribute = class {
    constructor(arr) { this.array = arr; }
};
THREE.PointsMaterial = class {};
THREE.Points = class {};
THREE.Float32Array = Float32Array;

console.warn('THREE.js stub loaded. Real Three.js library should be substituted.');
